#pragma GCC optimize("O3")
#include <bits/stdc++.h>
using namespace std;

using ll = long long;
#define pb push_back
#define mp make_pair
#define int ll
#define FOR(i,a,b) for(int i = (a); i <= (b); i++)
#define RE(i,n) FOR(i,1,n)
#define REP(i,n) FOR(i,0,(int)(n)-1)
#define R(i,n) REP(i,n)
#define VI vector<int>
#define PII pair<int,int>
#define FI first
#define SE second
#define ALL(x) (x).begin(), (x).end()
#define SZ(x) ((int)(x).size())

int n, m, P;

inline int add_mod(int a, int b) {
    a += b;
    if (a >= P) a -= P;
    return a;
}

inline int mul_mod(int a, int b) {
    return a * b % P;
}

inline void add_to(int &a, int b) {
    a = add_mod(a, b);
}

inline void mul_self(int &a, int b) {
    a = mul_mod(a, b);
}

int32_t main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cout << fixed << setprecision(11);
    cerr << fixed << setprecision(6);

    cin >> n >> m >> P;

    // binomial coefficients up to max(n,m)
    int M = max(n, m);
    vector<vector<int>> C(M + 1, vector<int>(M + 1, 0));
    for (int i = 0; i <= M; i++) {
        C[i][0] = 1;
        for (int j = 1; j <= i; j++) {
            C[i][j] = add_mod(C[i-1][j], C[i-1][j-1]);
        }
    }

    vector<int> dp1(m + 1, 0), ile(m + 1, 0);
    ile[0] = 1;

    for (int i = 1; i <= m; i++) {
        for (int j = 0; j < i; j++) {
            int val = 0;
            add_to(val, mul_mod(dp1[j], ile[i-j-1]));
            add_to(val, mul_mod(dp1[i-j-1], ile[j]));
            mul_self(val, j + 1);
            add_to(val, mul_mod(mul_mod(ile[i-j-1], ile[j]), j * (j + 1) / 2));
            mul_self(val, C[i-1][j]);
            add_to(dp1[i], val);

            val = C[i-1][j];
            mul_self(val, ile[j]);
            mul_self(val, ile[i-j-1]);
            mul_self(val, j + 1);
            add_to(ile[i], val);
        }
        add_to(ile[i], ile[i]);
        add_to(dp1[i], dp1[i]);
    }

    vector<vector<int>> dp2(n + 2, vector<int>(m + 1, 0));
    vector<vector<int>> dp3(n + 2, vector<int>(m + 1, 0));
    dp2[0][0] = 1;
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= m; j++) {
            for (int k = 0; j + k <= m && i + k + 1 <= n + 1; k++) {
                int val = dp2[i][j];
                mul_self(val, C[m-j][k]);
                mul_self(val, ile[k]);
                add_to(dp2[i + k + 1][j + k], val);

                int val3 = dp3[i][j];
                mul_self(val3, ile[k]);
                add_to(val3, mul_mod(dp1[k], dp2[i][j]));
                mul_self(val3, C[m-j][k]);
                add_to(dp3[i + k + 1][j + k], val3);
            }
        }
    }

    cout << dp3[n + 1][m] << "\n";
    return 0;
}
